#include <cstdarg>
#include <cassert>
#include <type_traits>
#include <utility>
int sum(int count, ...) {
    std::va_list arguments;
    va_start(arguments, count);
    int result = 0;
    for (int i = 0; i < count; ++i)
        result += va_arg(arguments, int);
    va_end(arguments);
    return result;
}
int main() { assert(sum(3, 2, 3, 4) == 9); }
